import{_ as a,c as o,o as r,ag as t}from"./chunks/framework.DRADY2L-.js";const h=JSON.parse('{"title":"Buddai MCP Servers","description":"","frontmatter":{},"headers":[],"relativePath":"mcp_servers/index.md","filePath":"mcp_servers/index.md"}'),i={name:"mcp_servers/index.md"};function s(n,e,d,c,l,p){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="buddai-mcp-servers" tabindex="-1">Buddai MCP Servers <a class="header-anchor" href="#buddai-mcp-servers" aria-label="Permalink to &quot;Buddai MCP Servers&quot;">​</a></h1><p>Folder containing the MCP servers that power Buddai. Each service exposes specific tools through the Model Context Protocol and is typically packaged into its own Docker image defined in <code>*.mcp.yml</code> files.</p><h2 id="image-building" tabindex="-1">Image building <a class="header-anchor" href="#image-building" aria-label="Permalink to &quot;Image building&quot;">​</a></h2><ul><li>The <code>docker-compose.yml</code> in this directory groups the build recipes to rebuild all images at once (<code>docker compose build</code>). It is meant as a local shortcut: it does not start running containers; it only facilitates consistent compilation of each service.</li></ul><h2 id="active-servers" tabindex="-1">Active servers <a class="header-anchor" href="#active-servers" aria-label="Permalink to &quot;Active servers&quot;">​</a></h2><ul><li><p><strong>Agenda (<code>agenda/</code>)</strong> – Node.js server wrapping the <code>agenda</code> library to schedule, snooze, and list reminders in MongoDB. <a href="./agenda/">README</a></p></li><li><p><strong>Apple Calendar (<code>calendarTool/</code>)</strong> – Syncs an iCloud/CalDAV calendar into MongoDB, generates local embeddings, and allows searching/creating events. <a href="./calendarTool/">README</a></p></li><li><p><strong>Google Maps (<code>drive/</code>)</strong> – Python service with routing and geocoding utilities backed by the Google Maps API. <a href="./drive/">README</a></p></li><li><p><strong>User Location (<code>location/</code>)</strong> – Saves and retrieves the user’s current location in MongoDB via a lightweight Node.js MCP. <a href="./location/">README</a></p></li><li><p><strong>Notes &amp; Docs (<code>notes/</code>)</strong> – Stores notes with embeddings (<code>nomic-embed-text-v1.5</code>) to enable semantic searches. <a href="./notes/">README</a></p></li><li><p><strong>Web Scraper (<code>scraper/</code>)</strong> – Extracts content from websites, Instagram, and YouTube, normalizes it, and indexes it with embeddings for later queries. <a href="./scraper/">README</a></p></li><li><p><strong>Supervisor (<code>supervisor/</code>)</strong> – Hybrid FastAPI + FastMCP service that coordinates LangGraph agents and MCP tools, exposing <code>run_supervisor</code>. <a href="./supervisor/">README</a></p></li><li><p><strong>Time Utilities (<code>time/</code>)</strong> – Python server providing current time, conversion, and difference calculations. <a href="./time/">README</a></p></li><li><p><strong>Weather (<code>weather/</code>)</strong> – Wraps the Open-Meteo API to obtain daily weather forecasts. <a href="./weather/">README</a></p></li></ul><h2 id="prototypes-and-legacy" tabindex="-1">Prototypes and legacy <a class="header-anchor" href="#prototypes-and-legacy" aria-label="Permalink to &quot;Prototypes and legacy&quot;">​</a></h2><ul><li><strong>Deprecated (<code>deprecated/</code>)</strong> – Contains old or experimental implementations, such as the legacy Apple Calendar and the <code>progress_tests</code> prototype. <a href="./deprecated/">README</a></li></ul>',8)])])}const u=a(i,[["render",s]]);export{h as __pageData,u as default};
